package com.lostvault;

import java.util.Set;

/** Dependency-free executable regression suite for core rules. */
public final class GameLogicTest {
    private static int passed=0;
    private static void check(boolean ok,String name){if(!ok)throw new AssertionError("FAILED: "+name);passed++;System.out.println("PASS: "+name);}
    private static void collectAllGemsAndClues(GameModel g){
        for(GameModel.Item item:g.level().items.stream().filter(i->i.kind==GameModel.Kind.GEM).toList()){g.teleportForTest(item.bounds.x(),item.bounds.y());g.update(0,0,0,false);}
        for(GameModel.Item item:g.level().items.stream().filter(i->i.kind==GameModel.Kind.CLUE).toList()){g.teleportForTest(item.bounds.x(),item.bounds.y());g.update(0,0,0,true);if(g.dialogueOpen())g.closeDialogue();}
    }
    public static void main(String[] args){
        double[] d=GameModel.normalizedMovement(1,1);check(Math.abs(Math.hypot(d[0],d[1])-1)<1e-9,"diagonal movement is normalized");
        double[] c=GameModel.normalizedMovement(1,0);check(Math.abs(c[0]-1)<1e-9&&c[1]==0,"cardinal movement remains unchanged");
        check(new Rect(0,0,10,10).intersects(new Rect(9,9,3,3)),"AABB detects overlap");check(!new Rect(0,0,10,10).intersects(new Rect(10,0,3,3)),"AABB touching edges is not overlap");
        UnlockCondition cond=new UnlockCondition(Set.of("B","C"),5);check(cond.isMet(Set.of("B","C"),5),"unlock accepts all clues and gem threshold");check(!cond.isMet(Set.of("B"),9),"unlock rejects missing clue");check(!cond.isMet(Set.of("B","C"),4),"unlock rejects insufficient gems");
        GameModel g=new GameModel();g.startNewRun();check(g.state()==GameModel.State.PLAYING&&g.levelNumber()==1,"new run starts level 1");check(g.lives()==3,"level starts with three lives");
        GameModel.Level l=g.level();GameModel.Item gem=l.items.stream().filter(i->i.kind==GameModel.Kind.GEM).findFirst().orElseThrow();double gx=gem.bounds.x(),gy=gem.bounds.y();g.update(0,0,0,false);g.teleportForTest(gx,gy);g.update(0,0,0,false);check(g.levelGems()==1&&g.totalGems()==1&&!gem.active,"gem collected once");g.teleportForTest(gx,gy);g.update(0,0,0,false);check(g.levelGems()==1&&g.totalGems()==1,"duplicate gem collection is a no-op");
        GameModel.Item clue=l.items.stream().filter(i->i.kind==GameModel.Kind.CLUE).findFirst().orElseThrow();g.teleportForTest(clue.bounds.x(),clue.bounds.y());g.update(0,0,0,true);if(g.dialogueOpen())g.closeDialogue();check(g.hasClue("A"),"clue id is recorded");g.teleportForTest(clue.bounds.x(),clue.bounds.y());g.update(0,0,0,false);check(g.collectedClues().size()==1,"duplicate clue collection is a no-op");
        g.setCheckpointForTest(450,700);g.teleportForTest(720,470);g.update(.016,0,0,false);check(g.lives()==2&&g.playerX()==450&&g.playerY()==700,"hazard costs a life and respawns at checkpoint");
        g.forceLivesForTest(1);g.teleportForTest(720,470);g.update(.016,0,0,false);check(g.levelNumber()==1&&g.lives()==3&&g.levelGems()==0,"last life restarts current level attempt");
        GameModel gate=new GameModel();gate.startNewRun();check(gate.levelNumber()==1,"level progression begins in order");boolean rejected=false;try{gate.startLevel(2);}catch(IllegalArgumentException ex){rejected=true;}check(rejected,"locked level cannot be entered directly");
        GameModel vault=new GameModel();vault.startNewRun();vault.teleportForTest(200,200);vault.debugStartLevel(3);check(!vault.vaultUnlocked()&&!vault.hasTreasure(),"vault begins locked and treasure absent");vault.debugSetClues(Set.of("A","B","C"));vault.teleportForTest(1025,595);vault.update(0,0,0,true);check(vault.puzzleOpen(),"vault constellation puzzle opens after required clues");vault.enterPuzzleSymbol(3);check(vault.puzzleInput().isEmpty()&&vault.puzzleOpen(),"wrong constellation symbol resets puzzle input");vault.enterPuzzleSymbol(1);vault.enterPuzzleSymbol(2);vault.enterPuzzleSymbol(3);check(vault.vaultPuzzleSolved(),"vault constellation accepts Wave-Thorn-Sun sequence");vault.teleportForTest(1285,345);vault.update(0,0,0,true);check(vault.vaultUnlocked()&&vault.treasureSpawned(),"vault unlock reveals treasure exactly once");vault.closeDialogue();vault.teleportForTest(1285,345);vault.update(0,0,0,true);check(vault.level().items.stream().filter(i->i.kind==GameModel.Kind.TREASURE).count()==1,"repeated interaction does not duplicate treasure");
        GameModel boat=new GameModel();boat.startNewRun();boat.debugStartLevel(3);boat.teleportForTest(1560,1020);boat.update(0,0,0,true);check(boat.state()!=GameModel.State.VICTORY,"boat cannot trigger victory without treasure");if(boat.dialogueOpen())boat.closeDialogue();boat.debugSetTreasure(true);boat.teleportForTest(1560,1020);boat.update(0,0,0,true);check(boat.state()==GameModel.State.VICTORY,"boat triggers victory after treasure when interacted");
        GameModel pause=new GameModel();pause.startNewRun();pause.togglePause();double x=pause.playerX();pause.update(1,1,0,false);check(pause.state()==GameModel.State.PAUSED&&pause.playerX()==x,"paused state freezes simulation");pause.resume();check(pause.state()==GameModel.State.PLAYING,"resume returns to gameplay");
        GameModel full=new GameModel();full.startNewRun();
        check(full.level().items.stream().filter(i->i.kind==GameModel.Kind.GEM).count()>=3&&full.level().items.stream().filter(i->i.kind==GameModel.Kind.CHECKPOINT).count()>=2,"Level 1 data has enough gems and checkpoints");
        collectAllGemsAndClues(full);full.teleportForTest(1645,1035);full.update(0,0,0,false);check(full.state()==GameModel.State.TRANSITION,"Level 1 completion transitions only after objectives");full.continueAfterTransition();check(full.levelNumber()==2&&full.state()==GameModel.State.PLAYING,"transition unlocks Level 2 in order");
        check(full.level().items.stream().filter(i->i.kind==GameModel.Kind.GEM).count()>=5&&full.level().items.stream().filter(i->i.kind==GameModel.Kind.CHECKPOINT).count()>=2&&full.level().items.stream().anyMatch(i->i.kind==GameModel.Kind.HAZARD),"Level 2 data has enough gems, checkpoints and hazards");
        collectAllGemsAndClues(full);full.teleportForTest(1510,880);full.update(0,0,0,true);check(!full.gateUnlocked(),"Level 2 gate remains locked before dial puzzle is solved");if(full.dialogueOpen())full.closeDialogue();full.teleportForTest(1105,625);full.update(0,0,0,true);check(full.puzzleOpen(),"Level 2 dial opens after both required clues");full.enterPuzzleSymbol(2);full.enterPuzzleSymbol(3);check(full.gatePuzzleSolved(),"Level 2 dial accepts Thorn-Sun sequence");full.teleportForTest(1510,880);full.update(0,0,0,true);check(full.gateUnlocked(),"Level 2 gate unlocks after clues and dial puzzle");if(full.dialogueOpen())full.closeDialogue();full.teleportForTest(1590,1010);full.update(0,0,0,false);check(full.state()==GameModel.State.TRANSITION,"Level 2 exit requires the gate and objectives");full.continueAfterTransition();check(full.levelNumber()==3,"Level 3 follows Level 2 without skipping");
        check(full.level().items.stream().filter(i->i.kind==GameModel.Kind.GEM).count()>=4&&full.level().items.stream().filter(i->i.kind==GameModel.Kind.CHECKPOINT).count()>=2,"Level 3 data has enough gems and checkpoints");
        collectAllGemsAndClues(full);full.teleportForTest(1025,595);full.update(0,0,0,true);full.enterPuzzleSymbol(1);full.enterPuzzleSymbol(2);full.enterPuzzleSymbol(3);full.teleportForTest(1285,345);full.update(0,0,0,true);check(full.vaultUnlocked()&&full.treasureSpawned(),"full run unlocks Vault after solving constellation");if(full.dialogueOpen())full.closeDialogue();full.teleportForTest(1320,425);full.update(0,0,0,true);if(full.dialogueOpen())full.closeDialogue();check(full.hasTreasure(),"treasure pickup works in the full run");full.teleportForTest(1560,1020);full.update(0,0,0,true);check(full.state()==GameModel.State.VICTORY,"full game progression reaches Victory");
        GameModel choices=new GameModel();choices.startNewRun();choices.teleportForTest(190,165);choices.update(0,0,0,true);check(choices.dialogueOpen()&&choices.dialogueChoices().length==3,"NPC dialogue offers three meaningful choices");choices.chooseDialogueOption(1);check(choices.inventory().contains("Rusty key"),"asking Mara for supplies grants a usable key");choices.closeDialogue();choices.teleportForTest(330,740);choices.update(0,0,0,true);check(choices.level().items.stream().anyMatch(i->i.id.equals("L1-CACHE")&&i.active),"rusty key reveals hidden chamber cache");choices.teleportForTest(375,760);choices.update(0,0,0,true);check(choices.inventory().contains("Captain's log"),"secret cache rewards an evidence item");choices.toggleInventory();check(choices.inventoryOpen(),"inventory overlay state toggles");choices.closeInventory();choices.toggleMap();check(choices.mapOpen(),"cartographer map overlay state toggles");choices.closeMap();
        GameModel escape=new GameModel();escape.startNewRun();escape.debugSetTreasure(true);escape.debugSetEscapeTimer(0.01);escape.update(0.05,0,0,false);check(escape.lives()==2&&escape.hasTreasure()&&escape.escapeTimer()==20,"escape countdown expiry costs a life and grants a final short escape window");
        GameModel mechanism=new GameModel();mechanism.startNewRun();mechanism.teleportForTest(860,830);mechanism.update(0,0,0,true);check(mechanism.level().items.stream().noneMatch(i->i.id.equals("L1-TIDE-BLOCK")&&i.active),"tidewheel visibly clears the blocked branch");check(!mechanism.level().solids.contains(new Rect(1340,650,50,150)),"tidewheel removes the matching collision blocker");
        System.out.println("\nAll "+passed+" checks passed.");
    }
}
